SET LOCAL statement_timeout='2000ms'; WITH scan AS MATERIALIZED (SELECT rakeback_amount,rakeback_rate,rake_generated,total_rake_paid FROM public.rakeback_periods WHERE status='pending' AND (period_end+1)::timestamp AT TIME ZONE 'UTC'<=statement_timestamp() ORDER BY id LIMIT 5001) SELECT statement_timestamp() checked_at,5001 row_cap,count(*) closed_pending_scanned,count(*)<5001 complete_for_closed_pending_filter,count(*) FILTER(WHERE rakeback_amount<0) negative_periods,count(*) FILTER(WHERE rakeback_amount>0 AND (rakeback_amount::text IN('NaN','Infinity','-Infinity') OR rakeback_amount<>round(rakeback_amount,2))) invalid_positive_amounts,count(*) FILTER(WHERE rakeback_amount>0 AND (rakeback_rate IS NULL OR rakeback_rate<0 OR rakeback_rate>1 OR rakeback_rate::text IN('NaN','Infinity','-Infinity'))) invalid_positive_rates,count(*) FILTER(WHERE rakeback_amount>0 AND (coalesce(rake_generated,total_rake_paid) IS NULL OR coalesce(rake_generated,total_rake_paid)<0 OR coalesce(rake_generated,total_rake_paid)::text IN('NaN','Infinity','-Infinity'))) invalid_positive_rake_basis FROM scan;
